  1300: ["My application was approved last week.", "Başvurum geçen hafta onaylandı."],
  1301: ["Fill in the application form completely and with a blue pen.", "Başvuru formunu eksiksiz ve mavi kalemle doldurun."],
  1302: ["You will receive a confirmation by post within five days.", "Beş gün içinde posta yoluyla bir onay yazısı alacaksınız."],
