  1304: ["The immigration service can reject an application if the details are incomplete.", "Göçmenlik dairesi, bilgiler eksikse başvuruyu reddedebilir."],
  1305: ["The municipality must approve the renovation first.", "Tadilatı önce belediyenin onaylaması gerekiyor."],
  1306: ["The processing period is a maximum of eight weeks.", "İşlem süresi en fazla sekiz haftadır."],
  1307: ["Send a copy of every supporting document with your letter.", "Her kanıtlayıcı belgenin bir kopyasını mektubunuzla birlikte gönderin."],
  1308: ["Bring a copy of your passport to the counter.", "Pasaportunuzun bir fotokopisini gişeye getirin."],
  1309: ["You keep the original yourself, we will make a scan.", "Aslını siz saklıyorsunuz, biz taramasını alıyoruz."],
  1310: ["Check carefully whether all your details are correct.", "Bütün bilgilerinizin doğru olup olmadığını iyice kontrol edin."],
  1311: ["Report any change of address immediately.", "Adresinizdeki her değişikliği hemen bildirin."],
  1312: ["You must report a change of address within five days.", "Taşındığınızı beş gün içinde bildirmeniz gerekir."],
  1313: ["Your address is in the municipality's population register.", "Adresiniz belediyenin nüfus kayıt sisteminde bulunuyor."],
  1314: ["For this application I need a birth certificate.", "Bu başvuru için doğum belgesine ihtiyacım var."],
